<script setup lang="ts">
import {computed,shallowRef,ref,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import {usePublication} from './usePublication';import type {Libraries,Folders} from '../../shared/api/publications';import type {components} from '../../shared/api/generated';import {ApiError} from '../../shared/api/client';
const props=defineProps<{meetingId:string;owner:boolean;locked:boolean}>();const emit=defineEmits<{changed:[];denied:[cause:unknown]}>();const app=useApplication();
const p=usePublication({...app.publications,authorize:async(id,s)=>{const n=await app.workspace.navigation(id,s);return n.relation!=='OWNER'?false:n.navigationState==='PUBLISHED_READ_ONLY'?'READ_ONLY':n.navigationState==='CHECK_PRODUCER';}},()=>app.session.current.value?.actor.enterpriseId??null,()=>props.meetingId,()=>props.owner,()=>app.minutesScopeReady.value,()=>props.locked,app.journals,cause=>{clear();emit('denied',cause);});
const libraries=shallowRef<Libraries|null>(null),folders=shallowRef<Folders|null>(null),library=ref(''),parent=ref<string|null>(null),folder=ref(''),destinationProvider=ref(''),error=ref(''),reading=ref(false),optional=ref<string[]>([]),requirementPage=ref(0),frozenPage=ref(0),attempts=shallowRef<components['schemas']['AttemptPage']|null>(null);let epoch=0,controller:AbortController|null=null;
const status=computed(()=>p.current.value?.publication),message=computed(()=>p.error.value instanceof Error?p.error.value.message:'发布状态暂不可用。');
async function read<T>(fn:(s:AbortSignal)=>Promise<T>,accept:(v:T)=>void){const turn=++epoch;controller?.abort();const request=new AbortController();controller=request;reading.value=true;error.value='';try{const v=await fn(request.signal);if(turn===epoch)accept(v);}catch(cause){if(turn===epoch){if(cause instanceof ApiError&&[401,403].includes(cause.status)){p.deny(cause);}error.value=cause instanceof Error?cause.message:'目录暂不可用。';}}finally{if(turn===epoch)reading.value=false;}}
function clear(){epoch++;controller?.abort();libraries.value=null;folders.value=null;library.value='';parent.value=null;folder.value='';destinationProvider.value='';optional.value=[];attempts.value=null;error.value='';reading.value=false;}
function loadLibraries(cursor:string|null=null){folders.value=null;library.value='';folder.value='';void read(s=>app.publications.libraries(props.meetingId,cursor,s),v=>libraries.value=v);}
function loadFolders(selectedLibrary:string,selectedParent:string|null=null,cursor:string|null=null){library.value=selectedLibrary;parent.value=selectedParent;folder.value='';void read(s=>app.publications.folders(props.meetingId,selectedLibrary,selectedParent,cursor,s),v=>{folders.value=v;destinationProvider.value=v.providerId;});}
async function run(fn:()=>Promise<void>){try{await fn();if(!p.error.value)emit('changed');}catch(cause){error.value=cause instanceof Error?cause.message:'操作暂不可用。';}}
function publish(){const item=folders.value?.items.find(x=>x.id===folder.value);if(!item||item.libraryId!==library.value||folders.value?.providerId!==destinationProvider.value){error.value='请从当前目的地列表选择文件夹。';return;}void run(()=>p.submit({providerId:destinationProvider.value,libraryId:library.value,folderId:item.id}));}
function loadAttempts(cursor:string|null=null){const id=status.value?.publicationId;if(id)void read(s=>app.publications.attempts(props.meetingId,id,cursor,s),v=>attempts.value=v);}
const stop=watch(()=>[app.session.current.value?.actor.enterpriseId,props.meetingId,props.owner,app.minutesScopeReady.value],()=>{clear();if(app.session.current.value)void p.reload();},{immediate:true,flush:'sync'});onUnmounted(()=>{stop();clear();p.dispose();});
</script>
<template><section class="publication"><header><h3>最终确认与发布</h3><button class="btn" :disabled="p.busy.value" @click="run(p.reload)">刷新最终状态</button></header><p v-if="p.error.value" role="alert">{{message}}</p><p v-if="error" role="alert">{{error}}</p>
 <template v-if="owner&&p.readiness.value"><p>{{p.readiness.value.ready?'当前已保存内容满足最终确认条件。':'尚未满足最终确认条件。'}}</p><ul><li v-for="b in p.readiness.value.blockers" :key="b">{{b}}</li></ul><p>待处置候选 {{p.readiness.value.pendingCandidateIds.length}} 项 · 未完成任务 {{p.readiness.value.outstandingTaskIds.length}} 项</p><ul><li v-for="r in p.readiness.value.required.slice(requirementPage*20,(requirementPage+1)*20)" :key="r.targetId+r.reviewKind">{{r.reviewKind==='ACTION_FIELDS'?'行动字段':'全文来源'}} · {{r.targetId}} · {{r.satisfied?'已满足':'待完成'}}</li></ul><button v-if="requirementPage>0" class="btn" @click="requirementPage--">上一页条件</button><button v-if="(requirementPage+1)*20<p.readiness.value.required.length" class="btn" @click="requirementPage++">下一页条件</button>
  <details v-if="p.readiness.value.optionalReviewIds.length"><summary>选择一并冻结的可选审阅</summary><label v-for="id in p.readiness.value.optionalReviewIds" :key="id"><input v-model="optional" type="checkbox" :value="id"/>{{id}}</label></details><button class="btn" :disabled="locked||p.busy.value||!p.readiness.value.ready" @click="run(()=>p.confirm(optional))">确认并冻结已保存版本</button>
 </template>
 <article v-if="p.final.value?.confirmation"><h4>已冻结版本</h4><p>{{p.final.value.confirmation.confirmed_at}} · {{p.final.value.confirmation.confirmed_by}}</p><h4>{{p.final.value.body?.title}}</h4><pre>{{p.final.value.body?.body}}</pre><details><summary>冻结的要素与行动字段</summary><div v-for="(items,category) in p.final.value.elements" :key="category"><h4>{{category}}</h4><p v-for="item in items.slice(frozenPage*20,(frozenPage+1)*20)" :key="item.id">{{item.body}}<span v-if="item.action"> · {{item.action.owner_display??'负责人未指定'}} · {{item.action.due_on??'日期未指定'}}</span></p></div><button class="btn" :disabled="frozenPage===0" @click="frozenPage--">上一页</button><button class="btn" :disabled="!Object.values(p.final.value.elements??{}).some(x=>(frozenPage+1)*20<x.length)" @click="frozenPage++">下一页</button></details><p>冻结审阅 {{p.final.value.reviewIds?.length??0}} 项。</p></article>
 <article v-if="status"><h4>发布状态</h4><dl><dt>远端结果</dt><dd>{{status.remoteOutcome}}</dd><dt>本地应用</dt><dd>{{status.applicationOutcome}}</dd><dt>当前状态</dt><dd>{{status.readOnlyReason}}</dd></dl><p v-if="status.remoteOutcome==='UNKNOWN'">远端结果尚未确定。请刷新查询，当前不能再次发送。</p><p v-if="status.applicationOutcome==='FENCED_MANUAL'">该发布关联需要人工处理，当前页面只提供结果查看。</p><p v-if="status.readOnlyReason==='PUBLISHED'">发布已完成，会议保持只读。</p><a v-if="status.officialDocumentUrl" :href="status.officialDocumentUrl" target="_blank" rel="noopener">查看正式文档</a><p v-else>正式文档入口当前不可用。</p><button v-if="owner" class="btn" @click="loadAttempts()">查看发布尝试</button><ul v-if="attempts"><li v-for="a in attempts.items" :key="a.attemptId">{{a.kind}} · {{a.remoteOutcome}} · {{a.applicationOutcome}} · {{a.createdAt}}</li></ul><button v-if="attempts?.hasMore" class="btn" @click="loadAttempts(attempts.nextCursor)">下一页尝试</button></article>
 <section v-else-if="owner&&p.final.value?.confirmation&&p.current.value"><h4>选择发布目的地</h4><button class="btn" :disabled="reading||locked" @click="loadLibraries()">读取知识库</button><ul v-if="libraries"><li v-for="lib in libraries.items" :key="lib.id"><button class="btn" @click="loadFolders(lib.id)">{{lib.name}}</button></li></ul><button v-if="libraries?.hasMore" class="btn" @click="loadLibraries(libraries.nextCursor)">更多知识库</button><template v-if="folders"><p>知识库：{{library}} · 文件夹：{{parent??'根目录'}}</p><button class="btn" @click="loadFolders(library)">返回根目录</button><ul><li v-for="f in folders.items" :key="f.id"><label><input v-model="folder" type="radio" :value="f.id"/>{{f.name}}</label><button class="btn" @click="loadFolders(library,f.id)">进入子目录</button></li></ul><button v-if="folders.hasMore" class="btn" @click="loadFolders(library,parent,folders.nextCursor)">更多文件夹</button><button class="btn" :disabled="!folder||locked||p.busy.value" @click="publish">发布已冻结版本到所选文件夹</button></template></section>
 <p v-if="p.command.state.value==='ACKNOWLEDGED'">已收到原操作回执；发布是否完成以上方当前状态为准。</p><button v-if="p.command.snapshot.value&&['PREPARED','UNCERTAIN'].includes(p.command.state.value)" class="btn" :disabled="p.busy.value" @click="run(p.retry)">{{p.command.snapshot.value.operation==='PUBLICATION_SUBMIT'?'查回原发布状态':'查回原最终确认'}}</button><button v-if="['CONFLICT','REJECTED'].includes(p.command.state.value)" class="btn" @click="p.reset();p.reload()">重新读取后再决定</button>
 </section></template>
<style scoped>.publication{border-top:1px solid var(--border);margin-top:24px;padding-top:12px}header{display:flex;justify-content:space-between;align-items:center}article{border:1px solid var(--border);border-radius:8px;padding:16px;margin:14px 0}pre{white-space:pre-wrap;line-height:1.7;max-height:350px;overflow:auto}button{margin:6px}label{display:block;margin:8px}dl{display:grid;grid-template-columns:100px 1fr;gap:10px}dd{margin:0}button:disabled{opacity:.5}</style>
